<?php
declare(strict_types=1);namespace Pam\Native\Nfc;use InvalidArgumentException;final readonly class NdefRecord{public function __construct(public int$tnf,public string$type,public string$id,public string$payload){if($tnf<0||$tnf>7||strlen($payload)>1048576)throw new InvalidArgumentException('Invalid NDEF record.');}public static function text(string$text,string$language='en'):self{if(strlen($language)>63||!preg_match('/^[A-Za-z-]+$/D',$language))throw new InvalidArgumentException('Invalid NDEF language.');return new self(1,'T','',chr(strlen($language)).$language.$text);}public static function uri(string$uri):self{if(filter_var($uri,FILTER_VALIDATE_URL)===false)throw new InvalidArgumentException('Invalid NDEF URI.');return new self(1,'U','',"\0".$uri);}public function json():array{return['tnf'=>$this->tnf,'typeBase64'=>base64_encode($this->type),'idBase64'=>base64_encode($this->id),'payloadBase64'=>base64_encode($this->payload)];}public static function fromJson(array$v):self{return new self((int)$v['tnf'],self::decode($v['typeBase64']??''),self::decode($v['idBase64']??''),self::decode($v['payloadBase64']??''));}private static function decode(string$v):string{$d=base64_decode($v,true);if($d===false)throw new InvalidArgumentException('Invalid NDEF base64.');return$d;}}
